"""Foundations-to-interviews course. Reference code is server-only."""
from copy import deepcopy
from interview_bank import LEVELS as BANK

REGIONS=[('Hello Shore','Printing, variables & types','🌱'),('Loop Lagoon','Conditions & repetition','🌊'),('Function Forest','Functions & collections','🌲'),('Ownership Grove','Borrowing & mutation','🍃'),('Builder Bay','Structs, enums & APIs','⚒'),('Algorithm Canyon','Searching & problem solving','⚙'),('Systems Ridge','Traits, errors & design','⛰'),('Concurrency Summit','Threads, futures & safety','🏔')]
LEVELS=[]
def add(title,topic,task,starter,solution,tests=None,expected=None,hint='Break the problem into small steps.',constraints=None):
    LEVELS.append(dict(title=title,topic=topic,task=task,starter=starter,solution=solution,tests=tests,
        mode='program' if expected is not None else 'function',expected=expected,
        examples=[('Program output',expected)] if expected is not None else [(a,b) for a,b in tests[:2]],
        constraints=constraints or (['Write a complete fn main() program. Match the output shown.','Use the concept described; do not just hardcode calculated results.'] if expected is not None else ['Keep the supplied function signature. Do not add main().','Handle every input described, including the edge cases.']),
        hints=[hint,'Use the examples to trace your code, then check empty inputs and boundary values where relevant.'],
        follow_up='Explain how your code works and why you chose these Rust operations.',complexity='Discuss the amount of work and memory your implementation uses.',lesson=topic))

PROGRAMS=[
('Hello, world!','Every executable starts in fn main(). println! prints a line; statements end with a semicolon.','Write your first Rust program. Print exactly Hello, world! on one line.','Hello, world!','println!("Hello, world!");','Put a println! macro call inside the braces of main.'),
('Two lines, one greeting','Each println! starts a new output line.','Print Welcome to Rust! on the first line and Let us learn. on the second.','Welcome to Rust!\nLet us learn.','println!("Welcome to Rust!"); println!("Let us learn.");','Use two print statements in the order you want the lines to appear.'),
('Build one line','print! does not add a newline; println! does.','Use print! followed by println! to compose Learning Rust is fun! on one line.','Learning Rust is fun!','print!("Learning Rust "); println!("is fun!");','Pay attention to spaces at the end of each printed piece.'),
('Meet a variable','let creates a binding. {} in a format string inserts a value.','Store the name Ferris in a variable, then print Hello, Ferris!.','Hello, Ferris!','let name="Ferris"; println!("Hello, {}!",name);','Pass your variable after the format string.'),
('Add the supplies','Integer variables support +, -, *, and /.','Store 7 apples and 5 oranges in separate variables. Print Total fruit: 12 using their sum.','Total fruit: 12','let apples=7; let oranges=5; println!("Total fruit: {}",apples+oranges);','Calculate the sum before or inside the formatting argument.'),
('Recharge the battery','let mut allows a binding to change after initialization.','Start energy at 20, add 15, and print Energy: 35. Use a mutable binding.','Energy: 35','let mut energy=20; energy+=15; println!("Energy: {}",energy);','Declare energy with mut, then update it.'),
('Area of a garden','Type annotations such as : i32 make a variable’s type explicit.','Declare integer width 6 and height 4. Compute the area and print Area: 24.','Area: 24','let width:i32=6; let height:i32=4; println!("Area: {}",width*height);','Area is width multiplied by height.'),
('Split the supplies','Integer division discards the fractional part; % gives the remainder.','Split 17 items among 5 explorers. Print Each: 3 and Left: 2 on separate lines.','Each: 3\nLeft: 2','let items=17;let people=5;println!("Each: {}",items/people);println!("Left: {}",items%people);','Use division and remainder on the same two values.'),
('Format a price','Floating-point numbers can be formatted with a fixed number of decimal places.','Store 12.5 as a floating-point price and print Price: 12.50 with exactly two decimal places.','Price: 12.50','let price:f64=12.5;println!("Price: {:.2}",price);','A precision specifier in the braces controls the decimal places.'),
('A boolean decision','Comparisons produce bool values, printed as true or false.','Set keys to 3. Compare it with the requirement of at least 2 and print Unlocked: true.','Unlocked: true','let keys=3;println!("Unlocked: {}",keys>=2);','Use a comparison expression as the printed value.'),
('Destructure coordinates','A tuple groups values. let (x,y) extracts both fields.','Create the tuple (4, 9), destructure it, and print x=4, y=9.','x=4, y=9','let point=(4,9);let(x,y)=point;println!("x={}, y={}",x,y);','Match the tuple shape on the left of the assignment.'),
('Shadow a measurement','Shadowing creates a new binding with the same name and can change its type.','Start with the text "12", parse it to i32 with a shadowing let, double it, and print Doubled: 24.','Doubled: 24','let value="12";let value:i32=value.parse().unwrap();println!("Doubled: {}",value*2);','parse() produces a Result; this fixed valid input can be unwrapped.'),
('Weather advice','if and else choose which code executes.','Set temperature to 12. Print Wear a jacket when it is below 18; otherwise print No jacket needed.','Wear a jacket','let temperature=12;if temperature<18{println!("Wear a jacket");}else{println!("No jacket needed");}','Write both branches even though this example takes the cold branch.'),
('Three-way score','An else if chain checks conditions in order.','Set score to 76. Print Excellent for at least 90, Passed for at least 60, otherwise Retry.','Passed','let score=76;if score>=90{println!("Excellent");}else if score>=60{println!("Passed");}else{println!("Retry");}','Check the highest threshold first.'),
('Even or odd','The remainder after division by 2 distinguishes even and odd integers.','Set number to 17 and print Odd or Even using a condition.','Odd','let number=17;if number%2==0{println!("Even");}else{println!("Odd");}','Compare the remainder with zero.'),
('Choose a direction','match selects a branch for a value; _ is a fallback.','Set direction to "north". Map north/south/east/west to N/S/E/W, and unknown input to ?. Print N.','N','let direction="north";let symbol=match direction{"north"=>"N","south"=>"S","east"=>"E","west"=>"W",_=>"?"};println!("{}",symbol);','Give every named direction a match arm and include a fallback.'),
('Count the steps','A for loop over 1..=5 includes both endpoints.','Print the numbers 1 through 5, one per line, using a for loop.','1\n2\n3\n4\n5','for n in 1..=5{println!("{}",n);}','Use an inclusive range.'),
('Sum a trail','A mutable accumulator keeps a running total.','Use a loop to sum 1 through 10 and print Sum: 55.','Sum: 55','let mut total=0;for n in 1..=10{total+=n;}println!("Sum: {}",total);','Initialize the accumulator before entering the loop.'),
('Countdown launch','while repeats while its condition remains true.','Use while to print 3, 2, 1, then Launch!, each on its own line.','3\n2\n1\nLaunch!','let mut n=3;while n>0{println!("{}",n);n-=1;}println!("Launch!");','Update the counter inside the loop to avoid running forever.'),
('Skip blocked steps','continue skips to the next iteration.','Print only the odd numbers from 1 through 7, one per line, using continue to skip even numbers.','1\n3\n5\n7','for n in 1..=7{if n%2==0{continue;}println!("{}",n);}','The condition that skips a number should run before printing.'),
('Stop at a limit','break exits the nearest loop.','Starting at 1, print successive integers and stop after printing 4. Use loop and break.','1\n2\n3\n4','let mut n=1;loop{println!("{}",n);if n==4{break;}n+=1;}','Decide whether to stop before incrementing again.'),
('Read an array','Arrays contain a fixed number of same-type values and support iteration.','Create [3, 6, 9] and print each value on its own line using a loop.','3\n6\n9','let values=[3,6,9];for value in values{println!("{}",value);}','You can iterate over the array directly.'),
('Locate an item','enumerate() pairs each item with its zero-based index.','Search [8, 4, 9, 2] for 9. Print Found at 2 using the index discovered in a loop.','Found at 2','let values=[8,4,9,2];for(i,value)in values.iter().enumerate(){if *value==9{println!("Found at {}",i);break;}}','The iterator provides an index and a borrowed value.'),
('Your first reusable function','Functions declare parameter types and a result type after ->. A final expression has no semicolon.','Define square(n: i32) -> i32, call it for 6 from main, and print Square: 36.','Square: 36','fn square(n:i32)->i32{n*n}println!("Square: {}",square(6));','A function may be defined inside main for this exercise, or outside it.'),
]
for title,topic,task,expected,body,hint in PROGRAMS:
    add(title,topic,task,'fn main() {\n    // Write your program here\n}\n','fn main() { '+body+' }',expected=expected,hint=hint)

def fn(title,topic,task,signature,body,cases,hint):
    add(title,topic,task,signature+' {\n    todo!()\n}',signature+' { '+body+' }',tests=cases,hint=hint)

# Module 3: reusable functions and collections (14).
fn('Calculate delivery fees','Parameters · arithmetic','A courier charges a base fee of 30 plus 8 per kilometre. Implement fee(km) for distances 0–1,000.','fn fee(km: u32) -> u32','30+8*km',[('fee(0)','30'),('fee(5)','70'),('fee(1000)','8030')],'Translate the pricing rule into an expression using the parameter.')
fn('Find a common divisor','Loops · Euclidean algorithm','Compute the greatest common divisor of two u32 values. gcd(0,0) is 0.','fn gcd(mut a: u32, mut b: u32) -> u32','while b!=0{let r=a%b;a=b;b=r;}a',[('gcd(18,24)','6'),('gcd(0,8)','8'),('gcd(0,0)','0'),('gcd(17,5)','1')],'Repeatedly replace the pair with the divisor and remainder.')
fn('Checked factorial','Option · overflow','Calculate n! as u64. Include 0!=1 and use None when multiplication overflows; n is at most 30.','fn factorial(n: u32) -> Option<u64>','let mut v=1u64;for i in 1..=n{v=v.checked_mul(i as u64)?;}Some(v)',[('factorial(0)','Some(1)'),('factorial(5)','Some(120)'),('factorial(21)','None')],'checked_mul gives an Option that can be propagated with ?.')
fn('Identify prime numbers','Conditions · efficient loops','Determine whether an integer n is prime, for n up to 1,000,000. Values below 2 are not prime.','fn is_prime(n: u32) -> bool','if n<2{return false;}let mut d=2;while d<=n/d{if n%d==0{return false;}d+=1;}true',[('is_prime(0)','false'),('is_prime(2)','true'),('is_prime(49)','false'),('is_prime(997)','true')],'A composite number has a divisor no greater than its square root.')
fn('Build the Fibonacci sequence','Vec · loops','Produce the first n Fibonacci values starting with 0,1; n is at most 40. Empty output is expected for n=0.','fn fibonacci(n: usize) -> Vec<u64>','let(mut a,mut b)=(0,1);let mut out=vec![];for _ in 0..n{out.push(a);(a,b)=(b,a+b);}out',[('fibonacci(0)','vec![]'),('fibonacci(1)','vec![0]'),('fibonacci(7)','vec![0,1,1,2,3,5,8]')],'Keep the two most recent values and append before advancing.')
fn('FizzBuzz labels','Branch ordering · String','Generate labels for 1 through n: multiples of both 3 and 5 are FizzBuzz, of 3 are Fizz, of 5 are Buzz, and all others use the number. n is at most 100.','fn fizzbuzz(n: u32) -> Vec<String>','(1..=n).map(|x|if x%15==0{"FizzBuzz".into()}else if x%3==0{"Fizz".into()}else if x%5==0{"Buzz".into()}else{x.to_string()}).collect()', [('fizzbuzz(5)','vec!["1","2","Fizz","4","Buzz"]'),('fizzbuzz(0)','Vec::<String>::new()'),('fizzbuzz(15)[14].clone()','"FizzBuzz"')],'Check the combined case before either single-divisor case.')
fn('Temperature conversion','Signed arithmetic','Convert integer Celsius to Fahrenheit using C*9/5+32. Integer division truncates toward zero; input is -100..100.','fn fahrenheit(celsius: i32) -> i32','celsius*9/5+32',[('fahrenheit(0)','32'),('fahrenheit(100)','212'),('fahrenheit(-40)','-40')],'Multiply before dividing so you do not lose precision too soon.')
fn('Find a range of readings','Slices · Option · tuples','Find the minimum and maximum reading in a slice. Empty input has no range.','fn min_max(values: &[i32]) -> Option<(i32,i32)>','let first=*values.first()?;let(mut lo,mut hi)=(first,first);for &v in values{lo=lo.min(v);hi=hi.max(v);}Some((lo,hi))',[('min_max(&[])','None'),('min_max(&[4,-2,8,1])','Some((-2,8))'),('min_max(&[7])','Some((7,7))')],'Seed both bounds from the first item rather than zero.')
fn('Count successful readings','Slice iteration · predicates','Count values strictly above zero in the readings. Zero is neither positive nor negative.','fn positive_count(values: &[i32]) -> usize','values.iter().filter(|&&x|x>0).count()',[('positive_count(&[-2,0,4,5])','2'),('positive_count(&[])','0'),('positive_count(&[-1])','0')],'Filter by the requested condition before counting.')
fn('Average a measurement batch','Type conversion · empty cases','Compute the average of i32 values as f64. Empty batches produce None; at most 1,000 values.','fn average(values: &[i32]) -> Option<f64>','if values.is_empty(){None}else{Some(values.iter().map(|&x|x as f64).sum::<f64>()/values.len() as f64)}',[('average(&[])','None'),('average(&[1,2])','Some(1.5)'),('average(&[-4,4])','Some(0.0)')],'Convert before dividing to preserve the fractional part.')
fn('Running totals','Accumulator · Vec','Build cumulative totals from signed i32 changes. Use i64 totals; preserve one output for every input.','fn running_totals(changes: &[i32]) -> Vec<i64>','let mut sum=0i64;changes.iter().map(|&x|{sum+=x as i64;sum}).collect()',[('running_totals(&[3,-1,5])','vec![3,2,7]'),('running_totals(&[])','vec![]'),('running_totals(&[i32::MAX,1])','vec![2147483647,2147483648]')],'A mutable total can be captured by the mapping closure.')
fn('Reverse a sentence','String slices · joining','Reverse the order of whitespace-separated words. Normalize separators to one space and omit leading/trailing whitespace.','fn reverse_words(text: &str) -> String','text.split_whitespace().rev().collect::<Vec<_>>().join(" ")',[('reverse_words("  learn   Rust now ")','"now Rust learn"'),('reverse_words("")','""'),('reverse_words("hi 🦀")','"🦀 hi"')],'Reverse word slices, not the bytes or characters within each word.')
fn('Count words consistently','HashMap · sorting','Count exact case-sensitive whitespace-separated words. Produce (word,count) pairs sorted lexicographically by word.','fn word_counts(text: &str) -> Vec<(String,usize)>','let mut m=std::collections::BTreeMap::new();for w in text.split_whitespace(){*m.entry(w.to_owned()).or_insert(0)+=1;}m.into_iter().collect()',[('word_counts("rust go rust")','vec![("go".into(),1),("rust".into(),2)]'),('word_counts("")','vec![]')],'An ordered map can combine counting with deterministic output order.')
fn('First unique character','Unicode · frequency maps','Find the first Unicode scalar value that occurs exactly once. Preserve original order when deciding which character is first.','fn first_unique(text: &str) -> Option<char>','let mut m=std::collections::HashMap::new();for c in text.chars(){*m.entry(c).or_insert(0)+=1;}text.chars().find(|c|m[c]==1)', [('first_unique("swiss")',"Some('w')"),('first_unique("aabb")','None'),('first_unique("🦀é🦀")',"Some('é')")],'Count first, then scan the original character order again.')

# Module 4: ownership and borrowing (12).
fn('Borrow and decorate','Borrowed input · owned output','Build a badge by surrounding a borrowed name with [ and ]. Do not change the input name.','fn badge(name: &str) -> String','format!("[{}]",name)',[('badge("Ferris")','"[Ferris]"'),('badge("")','"[]"'),('badge("🦀")','"[🦀]"')],'Formatting can create a new String while the original remains borrowed.')
fn('Append a log entry','Mutable String · separator rules','Append an entry to a mutable log, inserting a newline only when the log is nonempty. Empty entries are allowed.','fn append_log(log: &mut String, entry: &str)','if !log.is_empty(){log.push(\'\\n\');}log.push_str(entry);',[('{let mut s=String::new();append_log(&mut s,"start");append_log(&mut s,"done");s}','"start\\ndone"'),('{let mut s=String::new();append_log(&mut s,"");s}','""')],'Check the existing log before appending the separator.')
fn('Consume rejected readings','Ownership · into_iter','Consume a vector of readings and keep only nonnegative values, preserving order.','fn keep_valid(values: Vec<i32>) -> Vec<i32>','values.into_iter().filter(|x|*x>=0).collect()',[('keep_valid(vec![-1,0,3,-8])','vec![0,3]'),('keep_valid(vec![])','vec![]')],'A consuming iterator takes ownership of each value.')
fn('Swap without cloning','Generic mutable references','Swap two values through mutable references. T may not be Copy or Clone.','fn exchange<T>(left: &mut T, right: &mut T)','std::mem::swap(left,right);',[('{let(mut a,mut b)=(1,9);exchange(&mut a,&mut b);(a,b)}','(9,1)'),('{struct X(i32);let(mut a,mut b)=(X(2),X(4));exchange(&mut a,&mut b);(a.0,b.0)}','(4,2)')],'The standard library provides a safe primitive for swapping arbitrary values.')
fn('Borrow the longest label','Lifetimes · slices','Find the longest label by byte length in a slice of borrowed strings. On ties choose the earliest; empty input yields None.','fn longest_label<\'a>(labels: &[&\'a str]) -> Option<&\'a str>','let mut best=None;for &s in labels{if best.is_none_or(|b:&str|s.len()>b.len()){best=Some(s);}}best',[('longest_label(&["one","three","seven"])','Some("three")'),('longest_label(&[])','None'),('longest_label(&["",""])','Some("")')],'The result borrows a label, not the slice container itself.')
fn('Shared text prefix','UTF-8 boundaries · borrowing','Select the longest prefix shared by two strings, ending at a Unicode scalar boundary. Borrow the result from the first string.','fn common_prefix<\'a>(a: &\'a str, b: &str) -> &\'a str','let mut end=0;for((i,x),y)in a.char_indices().zip(b.chars()){if x!=y{break;}end=i+x.len_utf8();}&a[..end]',[('common_prefix("flower","flow")','"flow"'),('common_prefix("éclair","écart")','"éc"'),('common_prefix("abc","xyz")','""')],'char_indices gives safe byte boundaries while comparing characters.')
fn('Clean an inventory in place','Vec::retain · mutation','Remove zero and negative stock counts from a mutable vector while preserving the positive counts in order.','fn clean_stock(stock: &mut Vec<i32>)','stock.retain(|x|*x>0);',[('{let mut v=vec![0,4,-1,2];clean_stock(&mut v);v}','vec![4,2]'),('{let mut v=vec![-1];clean_stock(&mut v);v}','vec![]')],'retain edits a Vec using a predicate rather than requiring a second vector.')
fn('Clamp sensor values','Mutable slices · bounded values','Clamp each value into the inclusive range [low,high], where low <= high. Mutate the supplied slice.','fn clamp_readings(values: &mut [i32], low: i32, high: i32)','for x in values{*x=(*x).clamp(low,high);}',[('{let mut v=[-5,3,20];clamp_readings(&mut v,0,10);v}','[0,3,10]'),('{let mut v=[1,2];clamp_readings(&mut v,4,4);v}','[4,4]')],'Iteration over a mutable slice gives mutable references to elements.')
fn('Borrow distinct words','Lifetimes · HashSet','Find distinct whitespace-separated words, preserving their first appearance. Output slices must borrow from the original text.','fn distinct_words(text: &str) -> Vec<&str>','let mut seen=std::collections::HashSet::new();text.split_whitespace().filter(|w|seen.insert(*w)).collect()',[('distinct_words("red blue red green")','vec!["red","blue","green"]'),('distinct_words(" ")','Vec::<&str>::new()')],'HashSet can store borrowed slices while the source text remains alive.')
fn('Split a simple record','Borrowed fields · empty values','Split a comma-separated record and trim each field. Keep empty fields, including a final empty field. There is no quoting syntax.','fn record_fields(record: &str) -> Vec<&str>','record.split(\',\').map(str::trim).collect()',[('record_fields(" a, ,c,")','vec!["a","","c",""]'),('record_fields("")','vec![""]')],'Unlike word splitting, comma splitting preserves empty fields.')
fn('Join URL path pieces','String construction · normalization','Join two path pieces with exactly one slash at their boundary. Remove trailing slashes from left and leading slashes from right; preserve all other characters.','fn join_path(left: &str, right: &str) -> String','format!("{}/{}",left.trim_end_matches(\'/\'),right.trim_start_matches(\'/\'))',[('join_path("api///","//users")','"api/users"'),('join_path("","")','"/"'),('join_path("a/b","c/d")','"a/b/c/d"')],'Trim only the boundary characters; this is not a filesystem path validator.')
fn('Borrow a stored value','Lifetimes · key lookup','Search key/value pairs for an exact key, choosing the first matching pair. Borrow the value from the pairs; missing keys yield None.','fn lookup<\'a>(pairs: &\'a [(String,String)], key: &str) -> Option<&\'a str>','pairs.iter().find(|(k,_)|k==key).map(|(_,v)|v.as_str())',[('lookup(&[("a".into(),"one".into()),("a".into(),"two".into())],"a")','Some("one")'),('lookup(&[],"x")','None')],'Tie the returned lifetime to the owned pairs, not to the search key.')

# Module 5: eight new type/API exercises and four borrowed interview problems.
add('Model a rectangle','Structs · impl methods','Implement Rectangle with width and height u32 fields, area(), and perimeter(). Dimensions are at most 1,000.','struct Rectangle { width:u32, height:u32 }\nimpl Rectangle {\n fn area(&self)->u32 { todo!() }\n fn perimeter(&self)->u32 { todo!() }\n}', 'struct Rectangle{width:u32,height:u32}impl Rectangle{fn area(&self)->u32{self.width*self.height}fn perimeter(&self)->u32{2*(self.width+self.height)}}',tests=[('{let r=Rectangle{width:3,height:4};(r.area(),r.perimeter())}','(12,14)'),('{let r=Rectangle{width:0,height:5};(r.area(),r.perimeter())}','(0,10)')],hint='Methods borrow the instance through &self.')
add('Manage stock safely','Struct state · Result','Implement Stock::new(count), take(amount)->bool, and count(). A successful take removes stock; insufficient stock leaves the count unchanged.','struct Stock { /* fields */ }\nimpl Stock { fn new(n:u32)->Self{todo!()} fn take(&mut self,n:u32)->bool{todo!()} fn count(&self)->u32{todo!()} }','struct Stock{n:u32}impl Stock{fn new(n:u32)->Self{Self{n}}fn take(&mut self,n:u32)->bool{if n>self.n{false}else{self.n-=n;true}}fn count(&self)->u32{self.n}}',tests=[('{let mut s=Stock::new(5);(s.take(3),s.take(4),s.count())}','(true,false,2)'),('{let mut s=Stock::new(0);(s.take(0),s.count())}','(true,0)')],hint='Validate before modifying the stored quantity.')
add('Cycle a traffic light','Enums · exhaustive match','Define Light variants Red, Green, Yellow. Implement next(light) to cycle Red→Green→Yellow→Red.','#[derive(Debug,PartialEq)]\nenum Light { Red, Green, Yellow }\nfn next(light:Light)->Light { todo!() }','#[derive(Debug,PartialEq)]enum Light{Red,Green,Yellow}fn next(light:Light)->Light{match light{Light::Red=>Light::Green,Light::Green=>Light::Yellow,Light::Yellow=>Light::Red}}',tests=[('next(Light::Red)','Light::Green'),('next(Light::Green)','Light::Yellow'),('next(Light::Yellow)','Light::Red')],hint='Match each enum variant explicitly.')
add('Dispatch a command','Enums with data · validation','Commands Add(n), Multiply(n), and Reset update an i32 state. Implement apply(state,command). Inputs are small enough to avoid overflow.','enum Command { Add(i32), Multiply(i32), Reset }\nfn apply(state:i32,command:Command)->i32 { todo!() }','enum Command{Add(i32),Multiply(i32),Reset}fn apply(state:i32,command:Command)->i32{match command{Command::Add(n)=>state+n,Command::Multiply(n)=>state*n,Command::Reset=>0}}',tests=[('apply(4,Command::Add(3))','7'),('apply(4,Command::Multiply(-2))','-8'),('apply(9,Command::Reset)','0')],hint='Patterns can bind the data carried by an enum variant.')
add('Build a generic stack','Generics · LIFO ownership','Implement Stack<T>::new(), push(T), pop()->Option<T>, and len(). Pop removes the most recently pushed item; empty stacks yield None.','struct Stack<T> { /* fields */ }\nimpl<T> Stack<T>{fn new()->Self{todo!()}fn push(&mut self,x:T){todo!()}fn pop(&mut self)->Option<T>{todo!()}fn len(&self)->usize{todo!()}}','struct Stack<T>{v:Vec<T>}impl<T>Stack<T>{fn new()->Self{Self{v:vec![]}}fn push(&mut self,x:T){self.v.push(x)}fn pop(&mut self)->Option<T>{self.v.pop()}fn len(&self)->usize{self.v.len()}}',tests=[('{let mut s=Stack::new();s.push(1);s.push(2);(s.pop(),s.len(),s.pop(),s.pop())}','(Some(2),1,Some(1),None)'),('{let mut s=Stack::new();s.push(String::from("owned"));s.pop()}','Some(String::from("owned"))')],hint='A Vec already owns its elements and provides efficient operations at its end.')
add('Queue support tickets','VecDeque · FIFO ownership','Implement Queue<T>::new(), push(T), and pop()->Option<T>. Remove items in the same order they were added, without Clone bounds.','struct Queue<T>{/* fields */}\nimpl<T> Queue<T>{fn new()->Self{todo!()}fn push(&mut self,x:T){todo!()}fn pop(&mut self)->Option<T>{todo!()}}','struct Queue<T>{v:std::collections::VecDeque<T>}impl<T>Queue<T>{fn new()->Self{Self{v:Default::default()}}fn push(&mut self,x:T){self.v.push_back(x)}fn pop(&mut self)->Option<T>{self.v.pop_front()}}',tests=[('{let mut q=Queue::new();q.push(1);q.push(2);(q.pop(),q.pop(),q.pop())}','(Some(1),Some(2),None)'),('{let mut q=Queue::new();q.push(String::from("x"));q.pop()}','Some(String::from("x"))')],hint='Choose opposite ends for insertion and removal.')
add('Keep recent events','Bounded buffer · eviction','Implement Recent::new(capacity), push(i32), and values()->Vec<i32>. Keep only the most recent capacity events in arrival order. Capacity zero keeps nothing.','struct Recent{/* fields */}\nimpl Recent{fn new(capacity:usize)->Self{todo!()}fn push(&mut self,x:i32){todo!()}fn values(&self)->Vec<i32>{todo!()}}','struct Recent{cap:usize,v:std::collections::VecDeque<i32>}impl Recent{fn new(capacity:usize)->Self{Self{cap:capacity,v:Default::default()}}fn push(&mut self,x:i32){if self.cap==0{return;}if self.v.len()==self.cap{self.v.pop_front();}self.v.push_back(x);}fn values(&self)->Vec<i32>{self.v.iter().copied().collect()}}',tests=[('{let mut r=Recent::new(2);r.push(1);r.push(2);r.push(3);r.values()}','vec![2,3]'),('{let mut r=Recent::new(0);r.push(1);r.values()}','vec![]')],hint='Evict the oldest item when adding to a full buffer.')
add('Validate a network port','Typed errors · parsing','Parse a port into u16. Non-numeric or out-of-u16 values produce Invalid; zero produces Reserved. Trim surrounding whitespace.','#[derive(Debug,PartialEq)]enum PortError{Invalid,Reserved}\nfn parse_port(text:&str)->Result<u16,PortError>{todo!()}','#[derive(Debug,PartialEq)]enum PortError{Invalid,Reserved}fn parse_port(text:&str)->Result<u16,PortError>{let p=text.trim().parse::<u16>().map_err(|_|PortError::Invalid)?;if p==0{Err(PortError::Reserved)}else{Ok(p)}}',tests=[('parse_port(" 8080 ")','Ok(8080)'),('parse_port("0")','Err(PortError::Reserved)'),('parse_port("70000")','Err(PortError::Invalid)'),('parse_port("abc")','Err(PortError::Invalid)')],hint='Parsing range errors and application-specific validation are different failures.')
LEVELS.extend(deepcopy(BANK[9:13]))

# Module 6: two new algorithms, then the existing algorithm interviews.
fn('Insertion sort in place','Sorting · comparisons','Sort a generic mutable slice in ascending order using insertion sort. T is Ord but need not be Clone.','fn insertion_sort<T: Ord>(values: &mut [T])','for i in 1..values.len(){let mut j=i;while j>0&&values[j]<values[j-1]{values.swap(j,j-1);j-=1;}}',[('{let mut v=vec![3,1,2,1];insertion_sort(&mut v);v}','vec![1,1,2,3]'),('{let mut v:Vec<i32>=vec![];insertion_sort(&mut v);v}','vec![]')],'Insert each new item into the already sorted prefix by swapping backward.')
fn('Evaluate postfix arithmetic','Stacks · Result','Evaluate space-separated i64 integers with +, -, and * in postfix notation. Report None for missing operands, unknown tokens, overflow, or more than one final value.','fn postfix(text: &str) -> Option<i64>','let mut s=Vec::<i64>::new();for t in text.split_whitespace(){if let Ok(n)=t.parse(){s.push(n);}else{let b=s.pop()?;let a=s.pop()?;let n=match t{"+"=>a.checked_add(b),"-"=>a.checked_sub(b),"*"=>a.checked_mul(b),_=>None}?;s.push(n);}}if s.len()==1{s.pop()}else{None}',[('postfix("3 4 + 2 *")','Some(14)'),('postfix("8 3 -")','Some(5)'),('postfix("1 +")','None'),('postfix("1 2")','None'),('postfix("")','None')],'Pop the right operand before the left operand and check the final stack size.')
LEVELS.extend(deepcopy(BANK[:9]));LEVELS.append(deepcopy(BANK[18]))

# Module 7: richer borrowed APIs and trait-based interview designs.
LEVELS.extend(deepcopy(BANK[13:18]));LEVELS.extend(deepcopy(BANK[19:27]))

# Module 8: four introductions, then the nine advanced interviews.
fn('Receive a producer stream','mpsc channels · ownership','Spawn a producer thread that sends owned input integers through a channel. Collect them in order and join the producer before finishing.','fn channel_collect(values: Vec<i32>) -> Vec<i32>','let(tx,rx)=std::sync::mpsc::channel();let h=std::thread::spawn(move||{for v in values{tx.send(v).unwrap();}});let out=rx.into_iter().collect();h.join().unwrap();out',[('channel_collect(vec![4,1,9])','vec![4,1,9]'),('channel_collect(vec![])','vec![]')],'The receiver iterator ends when every sender is dropped.')
add('Issue unique tickets','Atomic fetch_add · shared ownership','Implement Tickets::new() and next()->usize. Every concurrent call must issue a distinct number starting at zero.','struct Tickets{/* fields */}\nimpl Tickets{fn new()->Self{todo!()}fn next(&self)->usize{todo!()}}','struct Tickets{next:std::sync::atomic::AtomicUsize}impl Tickets{fn new()->Self{Self{next:std::sync::atomic::AtomicUsize::new(0)}}fn next(&self)->usize{self.next.fetch_add(1,std::sync::atomic::Ordering::Relaxed)}}',tests=[('{let t=Tickets::new();(t.next(),t.next())}','(0,1)'),('{let t=std::sync::Arc::new(Tickets::new());let hs:Vec<_>=(0..8).map(|_|{let t=t.clone();std::thread::spawn(move||t.next())}).collect();let mut v:Vec<_>=hs.into_iter().map(|h|h.join().unwrap()).collect();v.sort();v}','(0..8).collect::<Vec<_>>()')],hint='Use one atomic read-modify-write operation, not a separate load and store.')
fn('Recover a poisoned mutex','Mutex poisoning · explicit policy','Read an i32 protected by a Mutex. If the mutex is poisoned, recover the contained value rather than panicking. This exercise deliberately assumes the scalar remains usable.','fn recover_value(value: &std::sync::Mutex<i32>) -> i32','*value.lock().unwrap_or_else(|poisoned|poisoned.into_inner())',[('recover_value(&std::sync::Mutex::new(7))','7'),('{let m=std::sync::Arc::new(std::sync::Mutex::new(3));let c=m.clone();let _=std::thread::spawn(move||{let mut g=c.lock().unwrap();*g=9;panic!("poison");}).join();recover_value(&m)}','9')],'PoisonError contains the guard; recovery must be an intentional application policy.')
add('Validate a newtype conversion','TryFrom · type invariants','Define Percent(u8) and implement TryFrom<u16> so only 0..=100 is accepted. Use the error "out of range" otherwise. Expose the inner value for these tests.','#[derive(Debug,PartialEq)]struct Percent(u8);\nimpl TryFrom<u16> for Percent{type Error=&\'static str;fn try_from(value:u16)->Result<Self,Self::Error>{todo!()}}','#[derive(Debug,PartialEq)]struct Percent(u8);impl TryFrom<u16> for Percent{type Error=&\'static str;fn try_from(value:u16)->Result<Self,Self::Error>{if value<=100{Ok(Self(value as u8))}else{Err("out of range")}}}',tests=[('Percent::try_from(75)','Ok(Percent(75))'),('Percent::try_from(0)','Ok(Percent(0))'),('Percent::try_from(101)','Err("out of range")'),('Percent::try_from(300)','Err("out of range")')],hint='Validate the original wider number before narrowing it.')
